import { Input as InputPrimitive } from '@base-ui/react/input';

import { DownloadIcon } from '@/registry/ndeko/lib/icons';
import { CONTROL_RECIPE } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Field, FieldLabel } from '@/registry/ndeko/ui/field';

const GROUP = cn(
  CONTROL_RECIPE,
  'flex h-8 items-stretch overflow-hidden',
  'focus-within:border-foreground/30 focus-within:ring-ring/25 dark:focus-within:border-foreground/25 focus-within:ring-[3px]'
);

const BARE_INPUT =
  'placeholder:text-muted-foreground/75 h-full min-w-0 flex-1 bg-transparent px-2.5 outline-none';

const SEGMENT_BUTTON =
  'text-muted-foreground hover:bg-foreground/[0.03] hover:text-foreground focus-visible:bg-foreground/5 focus-visible:text-foreground flex w-8 shrink-0 cursor-pointer items-center justify-center outline-none transition-colors disabled:pointer-events-none disabled:opacity-50';

const SEPARATOR =
  'bg-foreground/12 dark:bg-foreground/15 w-(--hairline) shrink-0';

export default function Input20() {
  return (
    <Field className='w-full max-w-xs'>
      <FieldLabel>Invoice number</FieldLabel>
      <div className={GROUP}>
        <InputPrimitive className={BARE_INPUT} placeholder='INV-2041' />
        <span className={SEPARATOR} aria-hidden='true' />
        <button
          type='button'
          className={SEGMENT_BUTTON}
          aria-label='Download invoice'
        >
          <DownloadIcon className='size-4' />
        </button>
      </div>
    </Field>
  );
}
